@Service
public class APUService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public APUService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new APUEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(APURepository.class) );
		this.validator		= applicationContext.getBean(APUValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		APU
	 */
		public APU createAPU( CreateAPUCommand command ) {

		APU entity = new APU();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAPUId( command.getAPUId() );
            entity.setModel( command.getModel() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of APU {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateAPUCommand
	 * @return		APU
	 */
	public APU updateAPU( UpdateAPUCommand command ) {

		APU entity = new APU();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setAPUId( command.getAPUId() );
            entity.setModel( command.getModel() );
            entity.setSupplier( command.getSupplier() );
            entity.setVariants( command.getVariants() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of APU {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteAPUCommand
	 */
	public void delete( DeleteAPUCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getAPUId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of APU {0} ", id );

	}

	/**
	 * Method to retrieve the APU via APUFetchOneSummary
	 * @param 	summary APUFetchOneSummary
	 * @return 	APUFetchOneResponse
	 */
	public APU getAPU( APUFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "APUFetchOneSummary arg cannot be null" );

		APU entity = null;
		UUID id = summary.getAPUId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a APU using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all APUs
	 *
	 * @return 	List<APU>
	 */
    public List<APU> getAllAPU() {
		List<APU> list = projector.findAll( new FindAllAPUQuery() );
		return list;
	}

	/**
	 * assign Supplier on APU
	 * @param		command AssignSupplierToAPUCommand
	 */
	public void assignSupplier( AssignSupplierToAPUCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignSupplier(command.getAPUId(), command.getAssignment());

	}

	/**
	 * unAssign Supplier on APU
	 * @param		command UnAssignSupplierFromAPUCommand
	 */
	public void unAssignSupplier( UnAssignSupplierFromAPUCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignSupplier(command.getAPUId());
	}
	

	/**
	 * add AircraftVariant to Variants
	 * @param		command AssignVariantsToAPUCommand
	 */
	public void addToVariants( AssignVariantsToAPUCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToVariants(command.getAPUId(), command.getAddTo());
	}

	/**
	 * remove AircraftVariant from Variants
	 * @param		command RemoveVariantsFromAPUCommand
	 */
	public void removeFromVariants( RemoveVariantsFromAPUCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromVariants(command.getAPUId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final APUEntityProjector projector;
	private final APUValidator validator;
	private APU aPU 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(APUService.class);
}
